/* From Uiverse.io by LightAndy1 - Source: Cohen - https://uiverse.io/cohencoo/proud-husky-84 - Tags: simple, animation, login, email, input, dark */
.__UIV_SCOPE__ .input {
  margin-top: 1rem;
  border-radius: 10px;
  outline: 2px solid #00a6fb;
  border: 0;
  font-family: "Montserrat", sans-serif;
  background-color: #d6f1ff;
  outline-offset: 3px;
  padding: 10px 12.5px;
  transition: all 0.2s ease;
  width: 250px;
}

.__UIV_SCOPE__ .input:hover {
  background-color: #fff;
}

.__UIV_SCOPE__ .input:focus {
  outline-offset: -6px;
  background-color: #d6f1ff;
}
